        d.model.as_any_mut().downcast_mut::<T>().map(f)
    }

    pub fn image(&self, unit: u8) -> Option<RegisterImage> {
        self.devices.get(&unit).map(|d| d.model.image(false))
    }

    /// Run fixed 100 ms steps up to `now_ms`. Devices under the stale fault are not stepped.
    pub fn advance_to(&mut self, now_ms: u64) {
        let Some(mut last) = self.last_step_ms else {
            self.last_step_ms = Some(now_ms);
            return;
        };
        if now_ms <= last {
            return;
        }
        let mut steps = (now_ms - last) / STEP_MS;
        if steps > MAX_STEPS_PER_ADVANCE {
            last += (steps - MAX_STEPS_PER_ADVANCE) * STEP_MS;
            steps = MAX_STEPS_PER_ADVANCE;
        }
        for _ in 0..steps {
            last += STEP_MS;
            for (unit, d) in self.devices.iter_mut() {
                if !self.faults.stale(*unit, last, d.requests) {
                    d.model.step(STEP_MS, &mut d.rng);
                }
            }
        }
        self.last_step_ms = Some(last);
    }

    /// Handle one request PDU addressed to `unit` at simulated time `now_ms`.
    pub fn handle_pdu(&mut self, unit: u8, pdu: &[u8], now_ms: u64) -> Reply {
        self.advance_to(now_ms);
        if unit == 0 {
            // Broadcast: writes apply to every device, nobody answers (serial line spec).
            if pdu.first().is_some_and(|fc| matches!(fc, 0x05 | 0x06 | 0x0F | 0x10)) {
                for d in self.devices.values_mut() {
                    let _ = server::handle(d.model.as_mut(), pdu, false);
                }
            }
            return Reply::silent();
        }
        let Some(d) = self.devices.get_mut(&unit) else {
            return Reply::silent();
        };
        let request = d.requests;
        d.requests += 1;
        let effect = self.faults.evaluate(unit, now_ms, request, &mut self.fault_rng);
        if effect.silent {
            return Reply::silent();
        }
        let pdu = match effect.exception {
            Some(code) => exception_response(pdu.first().copied().unwrap_or(0), ExceptionCode(code)).to_vec(),
            None => server::handle(d.model.as_mut(), pdu, effect.wrong_order),
        };
        Reply {
            pdu: Some(pdu),
            delay_ms: TURNAROUND_MS + effect.delay_ms,
            corrupt: effect.corrupt,
        }
    }

    /// Handle one RTU ADU. Bad CRC or unknown unit → silence.
    /// Returns the reply ADU and its delay.
    pub fn handle_rtu(&mut self, adu: &[u8], now_ms: u64) -> Option<(Vec<u8>, u64)> {
        let (unit, pdu) = match rtu::decode_adu(adu) {
            Ok(x) => x,
            Err(_) => {
                self.advance_to(now_ms);
                return None;
            }
        };
        let reply = self.handle_pdu(unit, pdu, now_ms);
        let pdu = reply.pdu?;
        let mut out = rtu::encode_adu(unit, &pdu).ok()?;
        if reply.corrupt {
            let last = out.len() - 1;
            out[last] ^= 0x5A;
        }
        Some((out, reply.delay_ms))
    }
}
//! Simulated device models. Every register map here is a simulator design
//! choice except the BGT-SMPS soil sensor, which follows its manual.

pub mod energy;
pub mod soil;
pub mod temp;
pub mod vfd;

use crate::image::RegisterImage;
use buslink_core::command::wire::WriteRequest;
use buslink_core::protocol::pdu::ExceptionCode;
use buslink_core::rng::SplitMix64;
use std::any::Any;

/// Fixed simulation step.
pub const STEP_MS: u64 = 100;

pub trait SimModel: Send + Any {
    fn model_id(&self) -> &'static str;
    /// Advance the process by `dt_ms` (always [`STEP_MS`] from the world).
    fn step(&mut self, dt_ms: u64, rng: &mut SplitMix64);
    /// Registers as served now.
    fn image(&self, wrong_order: bool) -> RegisterImage;
    /// Function codes the device implements (others answer exception 01).
    fn supports(&self, function: u8) -> bool;
    /// Apply a write after the server checked that every address exists and is
    /// writable. Validate all values before changing anything.
    fn apply(&mut self, write: &WriteRequest) -> Result<(), ExceptionCode>;
    fn as_any_mut(&mut self) -> &mut dyn Any;
}

pub const MODEL_IDS: [&str; 4] = [
    "bgt_smps_8in1",
    "vfd_basic",
    "temp_controller_basic",
    "energy_meter_basic",
];

/// Create a model by the `transport.simulator.model` ID used in profiles.
pub fn create(model_id: &str) -> Option<Box<dyn SimModel>> {
    Some(match model_id {
        "bgt_smps_8in1" => Box::new(soil::SoilSensor::new()),
        "vfd_basic" => Box::new(vfd::Vfd::new()),
        "temp_controller_basic" => Box::new(temp::TempController::new()),
        "energy_meter_basic" => Box::new(energy::EnergyMeter::new()),
        _ => return None,
    })
}

/// (address, value) pairs of a register write, for models that only take holding registers.
pub fn register_values(w: &WriteRequest) -> Option<Vec<(u16, u16)>> {
    match w {
        WriteRequest::SingleRegister { address, value } => Some(vec![(*address, *value)]),
        WriteRequest::MultipleRegisters { address, values } => Some(
            values
                .iter()
                .enumerate()
                .map(|(i, v)| (address.wrapping_add(i as u16), *v))
                .collect(),
        ),
        _ => None,
    }
}


