// BusLink Studio UI: shell, router and live-data subscription.
// Navigation follows the ISA-101 display levels: L1 overview, L2 device, L3 trends, L4 inspector/diagnostics.
import "./styles.css";
import { api, errorText, hasBackend, onFrame } from "./api.ts";
import { announce, clear, h, setText } from "./dom.ts";
import { lang, onLangChange, setLang, t } from "./i18n.ts";
import { loadProfiles } from "./profiles.ts";
import { store } from "./store.ts";
import { applyTheme, themeChoice, type ThemeChoice } from "./theme.ts";
import type { AlarmView, LinkView } from "./types.ts";
import { alarmBanner, alarmsView, alarmTitle } from "./views/alarms.ts";
import { connectView } from "./views/connect.ts";
import { dashboardView } from "./views/dashboard.ts";
import { inspectorView } from "./views/inspector.ts";
import { libraryView } from "./views/library.ts";
import { trainingView } from "./views/training.ts";
import { trendsView } from "./views/trends.ts";
import type { View } from "./views/view.ts";

applyTheme();

const NAV: [string, string][] = [
  ["#/dashboard", "nav.overview"],
  ["#/connect", "nav.connect"],
  ["#/library", "nav.library"],
  ["#/trends", "nav.trends"],
  ["#/inspector", "nav.inspector"],
  ["#/alarms", "nav.alarms"],
  ["#/training", "nav.training"],
];

const root = document.getElementById("app") ?? document.body;
let current: View | null = null;
const main = h("main", { id: "main", tabindex: -1 });
const navEl = h("nav", { class: "nav", "aria-label": t("nav.label") });
const notices = h("div", { class: "notices" });
const footer = h("footer", { class: "app-footer" }, "BusLink Studio");

function route(): void {
  current?.destroy?.();
  clear(main);
  const [path = "", arg] = location.hash.replace(/^#\/?/, "").split("/");
  const param = arg ? decodeURIComponent(arg) : undefined;
  const make: Record<string, () => View> = {
    dashboard: () => dashboardView(),
    device: () => dashboardView({ device: param }),
    connect: () => connectView(),
    library: () => libraryView(),
    trends: () => trendsView({ device: param }),
    inspector: () => inspectorView({ device: param }),
    alarms: () => alarmsView(),
    training: () => trainingView(),
  };
  const fallback = store.links.length ? "dashboard" : "connect";
  const factory = make[path] ?? make[fallback];
  current = factory ? factory() : null;
  if (current) main.append(current.el);
  for (const a of navEl.querySelectorAll("a")) {
    const active = a.getAttribute("href") === `#/${path === "device" ? "dashboard" : path || fallback}`;
    if (active) a.setAttribute("aria-current", "page");
    else a.removeAttribute("aria-current");
  }
  const heading = main.querySelector("h2");
  document.title = `${heading?.textContent ?? ""} · BusLink Studio`;
}

function renderNav(): void {
  clear(navEl);
  navEl.append(h("ul", null, ...NAV.map(([href, key]) => h("li", null, h("a", { href }, t(key))))));
}

function header(): HTMLElement {
  const langSel = h(
    "select",
    { id: "lang", "aria-label": t("settings.language") },
    h("option", { value: "id" }, "Bahasa Indonesia"),
    h("option", { value: "en" }, "English"),
  );
  langSel.value = lang();
  langSel.addEventListener("change", () => setLang(langSel.value === "id" ? "id" : "en"));
  const themeSel = h(
    "select",
    { id: "theme", "aria-label": t("settings.theme") },
    h("option", { value: "system" }, t("settings.theme.system")),
    h("option", { value: "light" }, t("settings.theme.light")),
    h("option", { value: "dark" }, t("settings.theme.dark")),
  );
  themeSel.value = themeChoice();
  themeSel.addEventListener("change", () => applyTheme(themeSel.value as ThemeChoice));
  return h(
    "header",
    { class: "app-header" },
    h("a", { class: "skip", href: "#main" }, t("nav.skip")),
    h("div", { class: "brand" }, h("span", { class: "brand-name" }, "BusLink Studio"), h("span", { class: "brand-sub" }, t("app.tagline"))),
    alarmBanner(),
    h("div", { class: "settings" }, langSel, themeSel),
    navEl,
  );
}

function renderNotices(): void {
  clear(notices);
  if (!hasBackend()) notices.append(h("p", { class: "notice error-text", role: "alert" }, t("app.no_backend")));
  if (store.historianError) notices.append(h("p", { class: "notice error-text" }, t("app.historian_error", { error: store.historianError })));
  if (store.droppedTotal > 0) notices.append(h("p", { class: "notice" }, t("app.dropped", { n: store.droppedTotal })));
  if (store.links.some((l) => l.simulated)) notices.append(h("p", { class: "notice sim-note" }, t("app.training_active")));
}

// Announce link changes and new alarm activations (never individual samples).
let prevLinks = new Map<string, string>();
let prevActive = new Set<string>();
function announceChanges(links: LinkView[] | null, alarms: AlarmView[] | null): void {
  if (links) {
    const now = new Map(links.map((l) => [l.id, l.state]));
    for (const l of links) {
      const before = prevLinks.get(l.id);
      if (before && before !== l.state) announce(t("announce.link", { link: l.label, state: t(`link.state.${l.state}`) }));
    }
    prevLinks = now;
  }
  if (alarms) {
    const active = new Set(alarms.filter((a) => a.active).map((a) => a.id));
    for (const a of alarms) {
      if (a.active && !prevActive.has(a.id) && a.state !== "SHELVED" && a.state !== "OUT_OF_SERVICE") {
        announce(t("announce.alarm", { p: a.priority, text: alarmTitle(a) }), a.priority === 1);
      }
    }
    prevActive = active;
  }
}

async function boot(): Promise<void> {
  shell();
  window.addEventListener("hashchange", route);
  if (!hasBackend()) {
    route();
    return;
  }
  try {
    await loadProfiles();
    const snap = await api.snapshot();
    store.applySnapshot(snap);
    prevLinks = new Map(snap.links.map((l) => [l.id, l.state]));
    prevActive = new Set(snap.alarms.alarms.filter((a) => a.active).map((a) => a.id));
    await onFrame((f) => {
      store.applyFrame(f);
      announceChanges(f.links, f.alarms?.alarms ?? null);
    });
    store.subscribe((c) => {
      if (c.links || c.points) renderNotices();
    });
  } catch (e) {
    notices.append(h("p", { class: "notice error-text", role: "alert" }, errorText(e)));
  }
  route();
  const appVersion = await api.appInfo().catch(() => null);
  if (appVersion?.profile_errors.length) {
    notices.append(h("p", { class: "notice error-text" }, t("app.profile_errors", { list: appVersion.profile_errors.join("; ") })));
  }
  info = appVersion;
  renderFooter();
}

let info: Awaited<ReturnType<typeof api.appInfo>> | null = null;
function renderFooter(): void {
  setText(footer, info ? `BusLink Studio ${info.version} · ${info.platform} · ${t("app.session")} ${info.session_id} · Apache-2.0` : "BusLink Studio");
}

function shell(): void {
  clear(root);
  renderNav();
  root.append(header(), notices, main, footer);
  renderNotices();
  renderFooter();
}

let booted = false;
const start = () => {
  if (booted) {
    // Language switch: rebuild the shell and the current view with the new strings.
    shell();
    route();
    return;
  }
  booted = true;
  void boot();
};
onLangChange(start);
start();
// The only module that talks to Tauri. Monitoring only: there is no write call here.
import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import type {
  AlarmDef,
  AlarmSnapshot,
  AppInfo,
  DeviceInspection,
  EventRow,
  ExportFormat,
  ExportResult,
  LiveFrame,
  LiveSnapshot,
  PortView,
  ProfileView,
  TrainingFault,
  TrainingStatus,
  TrendSeries,
} from "./types.ts";

export const FRAME_EVENT = "buslink://frame";

export function hasBackend(): boolean {
  return typeof (window as unknown as { __TAURI_INTERNALS__?: unknown }).__TAURI_INTERNALS__ !== "undefined";
}

/** Error text from a rejected command (Rust returns plain strings). */
export function errorText(e: unknown): string {
  if (typeof e === "string") return e;
  if (e instanceof Error) return e.message;
  return String(e);
}

export interface ConnectReq {
  kind: "rtu" | "tcp" | "rtu_over_tcp";
  port?: string;
  baud?: number;
  data_bits?: number;
  parity?: "none" | "even" | "odd";
  stop_bits?: number;
  host?: string;
  tcp_port?: number;
}

export const api = {
  appInfo: () => invoke<AppInfo>("app_info"),
  listPorts: () => invoke<PortView[]>("list_ports"),
  listProfiles: () => invoke<ProfileView[]>("list_profiles"),
  connect: (req: ConnectReq) => invoke<{ link_id: string; isolation_advice: boolean }>("connect_link", { req }),
  reconnect: (id: string) => invoke<void>("reconnect_link", { id }),
  disconnect: (id: string) => invoke<void>("disconnect_link", { id }),
  removeLink: (id: string) => invoke<void>("remove_link", { id }),
  startPolling: (id: string) => invoke<void>("start_polling", { id }),
  stopPolling: (id: string) => invoke<void>("stop_polling", { id }),
  addDevice: (req: { link_id: string; profile_key: string; unit_id: number; name?: string; poll_interval_ms?: number }) =>
    invoke<string>("add_device", { req }),
  removeDevice: (id: string) => invoke<void>("remove_device", { id }),
  snapshot: () => invoke<LiveSnapshot>("live_snapshot"),
  trend: (req: { device_id: string; tag_id: string; from_ms: number; to_ms: number; buckets: number }) =>
    invoke<TrendSeries>("trend_query", { req }),
  exportSession: (format: ExportFormat) => invoke<ExportResult>("export_session", { format }),
  inspect: (id: string) => invoke<DeviceInspection>("inspect_device", { id }),
  alarms: () => invoke<AlarmSnapshot>("alarm_list"),
  alarmAdd: (def: AlarmDef) => invoke<void>("alarm_add", { def }),
  alarmRemove: (id: string) => invoke<void>("alarm_remove", { id }),
  alarmAck: (id: string) => invoke<void>("alarm_ack", { id }),
  alarmShelve: (id: string, minutes: number) => invoke<void>("alarm_shelve", { req: { id, minutes } }),
  alarmUnshelve: (id: string) => invoke<void>("alarm_unshelve", { id }),
  alarmSetOos: (id: string, out_of_service: boolean) => invoke<void>("alarm_set_oos", { req: { id, out_of_service } }),
  alarmEvents: () => invoke<EventRow[]>("alarm_events"),
  alarmDefaults: (unit: string | null, span: number) =>
    invoke<{ deadband: number; delay_ms: number }>("alarm_defaults", { req: { unit, span } }),
  trainingStatus: () => invoke<TrainingStatus>("training_status"),
  trainingStart: () => invoke<TrainingStatus>("training_start"),
  trainingFault: (unit: number, fault: TrainingFault, seconds: number) =>
    invoke<TrainingStatus>("training_fault", { req: { unit, fault, seconds } }),
  trainingClear: (unit: number) => invoke<TrainingStatus>("training_clear", { unit }),
};

export function onFrame(cb: (f: LiveFrame) => void): Promise<UnlistenFn> {
  return listen<LiveFrame>(FRAME_EVENT, (e) => cb(e.payload));
}
import { h } from "../dom.ts";

export interface View {
  el: HTMLElement;
  destroy?: () => void;
}

/** A status line next to a form or action; text only, announced politely. */
export function statusLine(): { el: HTMLElement; set: (text: string, kind?: "ok" | "error" | "info") => void } {
  const el = h("p", { class: "status-line", role: "status", "aria-live": "polite" });
  return {
    el,
    set(text, kind = "info") {
      el.textContent = text;
      el.dataset.kind = kind;
    },
  };
}

/** Labeled form field with an error slot linked by aria-describedby (WCAG 3.3.1). */
export function field(
  id: string,
  label: string,
  control: HTMLInputElement | HTMLSelectElement,
  hint?: string,
): { el: HTMLElement; error: (text: string | null) => void } {
  control.id = id;
  const err = h("span", { class: "field-error", id: `${id}-err` });
  const hintEl = hint ? h("span", { class: "field-hint", id: `${id}-hint` }, hint) : null;
  control.setAttribute("aria-describedby", [hint ? `${id}-hint` : "", `${id}-err`].filter(Boolean).join(" "));
  const el = h("div", { class: "field" }, h("label", { for: id }, label), control, hintEl, err);
  return {
    el,
    error(text) {
      err.textContent = text ?? "";
      if (text) control.setAttribute("aria-invalid", "true");
      else control.removeAttribute("aria-invalid");
    },
  };
}

export function select(options: [string, string][], value?: string): HTMLSelectElement {
  const s = h("select", null, ...options.map(([v, label]) => h("option", { value: v }, label)));
  if (value !== undefined) s.value = value;
  return s;
}

/**
 * Re-render `container` without losing keyboard focus: elements carry `data-fk`
 * keys, and the focused key is restored after `render` (WCAG 2.4.3 / 2.4.7).
 */
export function preserveFocus(container: HTMLElement, render: () => void): void {
  const active = document.activeElement;
  const key = active instanceof HTMLElement && container.contains(active) ? active.dataset.fk : undefined;
  render();
  if (key) {
