    "comm_config",
    "notes",
];
const REQUIRED_TOP: [&str; 8] = [
    "schema_version",
    "profile_id",
    "profile_version",
    "vendor",
    "model",
    "support_level",
    "transport",
    "registers",
];
pub const REG_KEYS: [&str; 20] = [
    "id",
    "name",
    "description",
    "table",
    "address",
    "doc_address",
    "type",
    "length",
    "word_order",
