pub struct Preview {
    pub id: u64,
    pub device_id: String,
    pub device_name: String,
    pub simulated: bool,
    pub unit_id: u8,
    pub register_id: String,
    pub register_name: Text,
    pub table: Table,
    /// Manual label (or the conventional label in parentheses when the manual gives none).
    pub doc_address: String,
