    pub address: u16,
    pub function: u8,
    pub function_name: String,
    pub command_id: Option<String>,
    pub command_kind: Option<CommandKind>,
    pub command_label: Option<Text>,
    pub old_value: Option<f64>,
    pub old_raw: Option<Vec<u16>>,
    pub old_error: Option<String>,
