        clear(armBox);
        armBox.append(h("h3", { id: "arm-h" }, t("ctl.arm.title")));
        if (mine) {
          armText.textContent = t("ctl.armed", { s: secondsLeft(s.armed_remaining_ms), user: s.armed_user ?? "", role: t(`ctl.role.${s.armed_role ?? "operator"}`) });
