            s.armed_device ? disarmBtn : armBtn,
          );
          armBtn.dataset.fk = "arm";
        }
      });
      stopBox.hidden = !mine;
      for (const b of [...cmdButtons, ...stopButtons]) b.disabled = !mine || busy;
