            h("td", null, q ? (qualityBadge(q, tag?.exception ?? null, fmtAge(tag?.age_ms ?? null, lang())) ?? `GOOD · ${fmtAge(tag?.age_ms ?? null, lang())}`) : "—", ` ${tag ? fmtLocalTime(tag.value_ts_ms, lang()) : ""}`),
