python3 - <<'EOF'
import re
a=open('src/views/audit.ts').read()
start=a.index("export interface AuditFilter")
end=a.index("export function auditView")
block=a[start:end]
a=a[:start]+a[end:]
a=a.replace('import type { AuditRow } from "../types.ts";','import { filterAudit } from "../control.ts";\nimport type { AuditRow } from "../types.ts";')
open('src/views/audit.ts','w').write(a)
r=open('src/views/report.ts').read()
s2=r.index("/** Commands with their final result row")
e2=r.index("/** Plain-text cell helper")
block2=r[s2:e2]
r=r[:s2]+r[e2:]
r=r.replace('import type { AuditRow, ReportData } from "../types.ts";','import { commandRuns } from "../control.ts";\nimport type { ReportData } from "../types.ts";')
open('src/views/report.ts','w').write(r)
c=open('src/control.ts').read()
c=c.replace('import type { Ack, ProfileCommand, Register } from "./types.ts";','import type { Ack, AuditRow, ProfileCommand, Register } from "./types.ts";')
c+="\n"+block+block2
open('src/control.ts','w').write(c)
t=open('src/control.test.ts').read()
t=t.replace('import { actionLabel, ackKey, checkBounds, secondsLeft, splitCommands } from "./control.ts";\nimport type { ProfileCommand, Register } from "./types.ts";','import { actionLabel, ackKey, checkBounds, commandRuns, filterAudit, secondsLeft, splitCommands } from "./control.ts";\nimport type { AuditRow, ProfileCommand, Register } from "./types.ts";')
t+='''
function row(id: number, event: string, extra: Partial<AuditRow> = {}): AuditRow {
  return {
    id, ts_ms: id, session_id: "s", user: "u", role: "operator", event, device_id: "vfd", profile_id: "sim.vfd-basic",
    profile_version: "1.1.0", unit_id: 2, function: null, address: null, register_id: null, command_id: null,
    old_value: null, requested_value: null, raw_value_hex: null, request_hex: null, response_hex: null, exception: null,
    ack: null, readback: null, readback_value: null, note: null, ...extra,
  };
}

test("audit filter and command runs for the report", () => {
  const rows = [
    row(1, "arm"),
    row(2, "result", { command_id: "run", readback: "verified" }),
    row(3, "result", { command_id: "set_frequency", readback: "verified", request_hex: "02 06 00 01 0B B8 DB AD" }),
    row(4, "feedback", { command_id: "set_frequency", readback: "reached" }),
    row(5, "arm", { device_id: "temp" }),
  ];
  assert.equal(filterAudit(rows, { device: "vfd", event: "", text: "" }).length, 4);
  assert.equal(filterAudit(rows, { device: "", event: "result", text: "" }).length, 2);
  assert.deepEqual(filterAudit(rows, { device: "", event: "", text: "0b b8" }).map((r) => r.id), [3]);
  const runs = commandRuns(rows);
  assert.deepEqual(runs.map((r) => [r.result.command_id, r.feedback?.readback ?? null]), [["run", null], ["set_frequency", "reached"]]);
});
'''
open('src/control.test.ts','w').write(t)
EOF
npx tsc --noEmit 2>&1 | head; node --test src/*.test.ts 2>&1 | tail -9

