    step("connect to app over CDP", !!page, page?.url());
    await page.setViewport({ width: 1280, height: 900 });
    await waitFor(page, () => !!document.querySelector(".app-header"), 15000);
    await page.evaluate(() => {
      localStorage.setItem("buslink.lang", "en");
